def choose_move(observation):
    # Defensive defaults
    x = observation.get("position", {}).get("x", 0)
    y = observation.get("position", {}).get("y", 0)
    width = observation.get("grid", {}).get("width", 1)
    height = observation.get("grid", {}).get("height", 1)
    resources = observation.get("resources", [])
    enemies = observation.get("enemies", [])
    allies = observation.get("allies", [])
    mode = observation.get("mode", "")

    # Default aim: stay put
    dx = 0
    dy = 0

    # Helper: clamp to grid
    def in_bounds(nx, ny):
        return 0 <= nx < width and 0 <= ny < height

    # Strategy by mode (defensive, robust across modes)
    if mode == "resource_collection":
        # Move towards nearest resource if available, else explore randomly small
        if resources:
            # pick closest resource
            best = None
            best_d = None
            for r in resources:
                rx = r.get("x", 0)
                ry = r.get("y", 0)
                d = abs(rx - x) + abs(ry - y)
                if best is None or d < best_d:
                    best = (rx, ry)
                    best_d = d
            if best is not None:
                rx, ry = best
                if rx > x:
                    dx = 1
                elif rx < x:
                    dx = -1
                else:
                    dx = 0
                if ry > y:
                    dy = 1
                elif ry < y:
                    dy = -1
                else:
                    dy = 0
    elif mode == "pursuit_evasion":
        # Simple pursuit: move toward nearest "evader" if present, else toward center
        if enemies:
            best = None
            best_d = None
            for e in enemies:
                ex = e.get("x", 0)
                ey = e.get("y", 0)
                d = abs(ex - x) + abs(ey - y)
                if best is None or d < best_d:
                    best = (ex, ey)
                    best_d = d
            if best is not None:
                ex, ey = best
                if ex > x:
                    dx = 1
                elif ex < x:
                    dx = -1
                else:
                    dx = 0
                if ey > y:
                    dy = 1
                elif ey < y:
                    dy = -1
                else:
                    dy = 0
        else:
            # no enemies visible, drift toward center
            cx = width // 2
            cy = height // 2
            if cx > x:
                dx = 1
            elif cx < x:
                dx = -1
            else:
                dx = 0
            if cy > y:
                dy = 1
            elif cy < y:
                dy = -1
            else:
                dy = 0
    elif mode == "territory_control":
        # Move to influence border-adjacent cells: head toward center then outward
        cx = width // 2
        cy = height // 2
        # prefer moving toward center if far from influence
        if abs(x - cx) > abs(y - cy):
            dx = 1 if cx > x else -1 if cx < x else 0
            dy = 0
        else:
            dy = 1 if cy > y else -1 if cy < y else 0
            dx = 0
        # If there are allies nearby, try to spread to empty neighboring cell
        if allies:
            for a in allies:
                ax = a.get("x", 0)
                ay = a.get("y", 0)
                if ax == x and ay == y:
                    # try to move orthogonally to free space
                    if in_bounds(x+1, y) and (observation.get("grid", {}).get("blocked", {}).find or None) is None:
                        dx, dy = 1, 0
                        break
                    if in_bounds(x-1, y):
                        dx, dy = -1, 0
                        break
                    if in_bounds(x, y+1):
                        dx, dy = 0, 1
                        break
                    if in_bounds(x, y-1):
                        dx, dy = 0, -1
                        break

    # Final safety: ensure dx, dy in bounds movement
    nx = x + dx
    ny = y + dy
    if not in_bounds(nx, ny):
        # fallback to staying or small micro-adjustment
        dx, dy = 0, 0
    return [dx, dy]

